import math

def is_multiply_prime(a):
    """
    Returns True if the given number is the multiplication of 3 prime numbers,
    and False otherwise. Assumes that a is less than 100.
    """
    def is_prime(n):
        """Returns True if n is a prime number, False otherwise."""
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, a) if is_prime(i)]
    for i in primes:
        for j in primes:
            for k in primes:
                if i * j * k == a:
                    return True
    return False
